-- =====================================================================================
--  INSTALACION COMPLETA DE LA BASE DE DATOS DE CUENTAS POR COBRAR (CxC)  -  ORACLE 19c / 21c
-- =====================================================================================
--  Que hace este script (un solo archivo, se ejecuta de principio a fin):
--    1. Verifica que el esquema este vacio (para no pisar datos por accidente).
--    2. Crea las 39 tablas que usa el sistema CxC, con sus llaves primarias, llaves
--       foraneas, restricciones CHECK/UNIQUE, columnas identity e indices.
--    3. Carga datos de prueba coherentes (los mismos para todo el equipo).
--    4. Deja los contadores automaticos (identity) listos para seguir insertando.
--    5. Muestra una verificacion final.
--
--  Las tablas incluyen las que CxC comparte con otros modulos y necesita para funcionar:
--  EMPLEADO, DEPARTAMENTO, MONEDA y MB_BANCO. No incluye tablas de Compras, CxP ni Bancos.
--
--  COMO EJECUTARLO
--    * SQL Developer: abre este archivo conectado como el USUARIO/ESQUEMA DONDE QUIERES LA
--      BASE (idealmente uno nuevo y vacio) y pulsa "Ejecutar script" (F5, no Ctrl+Enter).
--    * SQL*Plus:      sqlplus USUARIO/CLAVE@HOST:1521/SERVICIO @00_instalacion_completa_cxc.sql
--
--  CUIDADO! No lo ejecutes conectado al esquema del servidor compartido: el paso 1 lo
--  detendra si ya existen tablas de CxC, pero la forma segura es usar un esquema propio.
--
--  CREAR UN ESQUEMA LOCAL VACIO (una sola vez, como SYSDBA / SYSTEM):
--      ALTER SESSION SET CONTAINER = ORCLPDB;      -- solo si tu Oracle es multitenant
--      CREATE USER CXC_LOCAL IDENTIFIED BY "TuClaveLocal123";
--      GRANT CREATE SESSION, CREATE TABLE, CREATE SEQUENCE, CREATE VIEW TO CXC_LOCAL;
--      ALTER USER CXC_LOCAL QUOTA UNLIMITED ON USERS;
--
--  USUARIOS DE PRUEBA (todos con la misma contrasena):   Cxc#Demo2026
--     admin (ADMIN)
--     supervisor (ADMIN)
--     operador (OPERADOR)
--     cobrador1 (OPERADOR)
--     cobrador2 (OPERADOR)
--     consulta (CONSULTA)
--     flopez (OPERADOR)
--     admin_rescate (ADMIN)
--
--  Las fechas de los datos son RELATIVAS a la fecha en que ejecutas el script (hoy, hace 10
--  dias, etc.), asi que siempre se ven recientes y hay documentos vencidos y por vencer.
--
--  Generado el 2026-10-30 a partir del esquema real del servidor.
-- =====================================================================================

SET DEFINE OFF
SET SQLBLANKLINES ON
SET FEEDBACK OFF
SET VERIFY OFF
SET LINESIZE 200
SET PAGESIZE 200
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

PROMPT =====================================================================
PROMPT  Instalacion de CxC en el esquema:
SELECT '  ' || USER || '  @  ' || SYS_CONTEXT('USERENV', 'DB_NAME') AS ESQUEMA FROM DUAL;
PROMPT =====================================================================

-- 1) Proteccion: no instalar sobre un esquema que ya tiene tablas de CxC
DECLARE
  n NUMBER;
BEGIN
  SELECT COUNT(*) INTO n FROM USER_TABLES
   WHERE TABLE_NAME IN ('CLIENTE', 'CXC_DOCUMENTOS', 'CXC_PAGOS', 'SEG_USUARIOS', 'EMPLEADO');
  IF n > 0 THEN
    RAISE_APPLICATION_ERROR(-20001,
      'Este esquema ya tiene tablas de CxC. Usa un esquema vacio o ejecuta antes 00_limpiar_esquema_cxc.sql.');
  END IF;
END;
/

PROMPT
PROMPT [1/4] Creando tablas...

-- CXC_CONDICIONES_CREDITO
CREATE TABLE "CXC_CONDICIONES_CREDITO" 
   (	"ID_CONDICION" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"DIAS_CREDITO" NUMBER NOT NULL ENABLE, 
	"PORCENTAJE_MORA" NUMBER(7,4), 
	"DIAS_GRACIA" NUMBER, 
	"ESTADO" CHAR(1) DEFAULT 'A' NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXC_CONDICIONES_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "PK_CXC_CONDICIONES_CREDITO" PRIMARY KEY ("ID_CONDICION")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_COND_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE
   ) ;

-- CXC_EMPRESAS
CREATE TABLE "CXC_EMPRESAS" 
   (	"ID_EMPRESA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(150) NOT NULL ENABLE, 
	"NIT" VARCHAR2(20), 
	"ESTADO" CHAR(1) DEFAULT 'A' NOT NULL ENABLE, 
	"DIRECCION" VARCHAR2(250), 
	"GIRO_COMERCIAL" VARCHAR2(200), 
	 CONSTRAINT "CK_CXC_EMPRESAS_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "PK_CXC_EMPRESAS" PRIMARY KEY ("ID_EMPRESA")
  USING INDEX  ENABLE
   ) ;

-- CXC_FORMAS_PAGO
CREATE TABLE "CXC_FORMAS_PAGO" 
   (	"ID_FORMA_PAGO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(80) NOT NULL ENABLE, 
	"REQUIERE_REFERENCIA" CHAR(1) DEFAULT 'N' NOT NULL ENABLE, 
	"ESTADO" CHAR(1) DEFAULT 'A' NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXC_FORMAS_PAGO_REQ" CHECK (REQUIERE_REFERENCIA IN ('S','N')) ENABLE, 
	 CONSTRAINT "CK_CXC_FORMAS_PAGO_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "PK_CXC_FORMAS_PAGO" PRIMARY KEY ("ID_FORMA_PAGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_FP_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "CK_CXC_FP_REQ_REF" CHECK (REQUIERE_REFERENCIA IN ('S','N')) ENABLE
   ) ;

-- CXC_SEGMENTOS_CLIENTE
CREATE TABLE "CXC_SEGMENTOS_CLIENTE" 
   (	"ID_SEGMENTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(5) NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(80) NOT NULL ENABLE, 
	"REDUCCION_MORA" NUMBER(7,4) DEFAULT 0 NOT NULL ENABLE, 
	"ESTADO" CHAR(1) DEFAULT 'A' NOT NULL ENABLE, 
	 CONSTRAINT "CK_CXC_SEGMENTOS_REDUCCION" CHECK ("REDUCCION_MORA" BETWEEN 0 AND 100) ENABLE, 
	 CONSTRAINT "CK_CXC_SEGMENTOS_ESTADO" CHECK ("ESTADO" IN ('A', 'I')) ENABLE, 
	 CONSTRAINT "PK_CXC_SEGMENTOS_CLIENTE" PRIMARY KEY ("ID_SEGMENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_SEGMENTOS_CODIGO" UNIQUE ("CODIGO")
  USING INDEX  ENABLE
   ) ;

-- CXC_SUCURSALES
CREATE TABLE "CXC_SUCURSALES" 
   (	"ID_SUCURSAL" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_EMPRESA" NUMBER NOT NULL ENABLE, 
	"NOMBRE" VARCHAR2(120) NOT NULL ENABLE, 
	"DIRECCION" VARCHAR2(250), 
	"ESTADO" CHAR(1) DEFAULT 'A' NOT NULL ENABLE, 
	"LATITUD" NUMBER(9,6), 
	"LONGITUD" NUMBER(9,6), 
	 CONSTRAINT "CK_CXC_SUCURSALES_ESTADO" CHECK (ESTADO IN ('A','I')) ENABLE, 
	 CONSTRAINT "PK_CXC_SUCURSALES" PRIMARY KEY ("ID_SUCURSAL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_SUC_LATITUD" CHECK (LATITUD IS NULL OR LATITUD BETWEEN -90 AND 90) ENABLE, 
	 CONSTRAINT "CK_CXC_SUC_LONGITUD" CHECK (LONGITUD IS NULL OR LONGITUD BETWEEN -180 AND 180) ENABLE, 
	 CONSTRAINT "FK_CXC_SUCURSALES_EMPRESA" FOREIGN KEY ("ID_EMPRESA")
	  REFERENCES "CXC_EMPRESAS" ("ID_EMPRESA") ENABLE
   ) ;

-- CXC_TIPOS_DOCUMENTO
CREATE TABLE "CXC_TIPOS_DOCUMENTO" 
   (	"ID_TIPO_DOCUMENTO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO" VARCHAR2(20) NOT NULL ENABLE, 
