  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_TIPOS_DOCUMENTO_COD" UNIQUE ("CODIGO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_TIPOS_DOC_ES_MORA" CHECK ("ES_MORA" IN ('S', 'N')) ENABLE
   ) ;

-- CXC_TRAMOS_MORA
CREATE TABLE "CXC_TRAMOS_MORA" 
   (	"ID_TRAMO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
