	"ESTADO" VARCHAR2(10) DEFAULT 'ACTIVO' NOT NULL ENABLE, 
	"INTENTOS_FALLIDOS" NUMBER(3,0) DEFAULT 0 NOT NULL ENABLE, 
	"BLOQUEADO_HASTA" TIMESTAMP (6), 
	"DEBE_CAMBIAR_CLAVE" CHAR(1) DEFAULT 'S' NOT NULL ENABLE, 
	"FECHA_CLAVE" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	"ULTIMO_LOGIN" TIMESTAMP (6), 
	"FECHA_CREACION" TIMESTAMP (6) DEFAULT SYSTIMESTAMP NOT NULL ENABLE, 
	 CONSTRAINT "CK_SEG_USU_ESTADO" CHECK (ESTADO IN ('ACTIVO', 'INACTIVO')) ENABLE, 
	 CONSTRAINT "CK_SEG_USU_DEBE_CLAVE" CHECK (DEBE_CAMBIAR_CLAVE IN ('S', 'N')) ENABLE, 
	 CONSTRAINT "CK_SEG_USU_INTENTOS" CHECK (INTENTOS_FALLIDOS >= 0) ENABLE, 
	 CONSTRAINT "PK_SEG_USUARIOS" PRIMARY KEY ("ID_USUARIO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_SEG_USU_ROL" CHECK (ROL IN ('ADMIN', 'OPERADOR', 'CONSULTA', 'COBRADOR')) ENABLE, 
	 CONSTRAINT "FK_SEG_USU_EMPLEADO" FOREIGN KEY ("ID_EMPLEADO")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE
   ) ;

