-- CXC_FACTURA_FEL
CREATE TABLE "CXC_FACTURA_FEL" 
   (	"ID_FACTURA_FEL" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_DOCUMENTO" NUMBER NOT NULL ENABLE, 
