	"UUID_AUTORIZACION" VARCHAR2(36) NOT NULL ENABLE, 
	"SERIE_FEL" VARCHAR2(8) NOT NULL ENABLE, 
	"NUMERO_FEL" NUMBER(12,0) NOT NULL ENABLE, 
	"TIPO_DTE" VARCHAR2(6) DEFAULT 'FACT' NOT NULL ENABLE, 
	"FECHA_EMISION" DATE NOT NULL ENABLE, 
	"FECHA_CERTIFICACION" DATE NOT NULL ENABLE, 
	"NIT_EMISOR" VARCHAR2(20) NOT NULL ENABLE, 
	"NOMBRE_EMISOR" VARCHAR2(150) NOT NULL ENABLE, 
	"NIT_RECEPTOR" VARCHAR2(20) NOT NULL ENABLE, 
	"NOMBRE_RECEPTOR" VARCHAR2(150) NOT NULL ENABLE, 
	"SUBTOTAL_GRAVADO" NUMBER(12,2) NOT NULL ENABLE, 
	"IVA" NUMBER(12,2) NOT NULL ENABLE, 
	"TOTAL" NUMBER(12,2) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(12) DEFAULT 'CERTIFICADA' NOT NULL ENABLE, 
	"XML_DTE" CLOB, 
	"ID_EMPLEADO_EMISION" NUMBER NOT NULL ENABLE, 
	"FECHA_ANULACION" DATE, 
	"UUID_ANULACION" VARCHAR2(36), 
	"MOTIVO_ANULACION" VARCHAR2(250), 
	"ID_EMPLEADO_ANULACION" NUMBER, 
	 CONSTRAINT "CK_CXC_FEL_ESTADO" CHECK (ESTADO IN ('CERTIFICADA', 'ANULADA')) ENABLE, 
	 CONSTRAINT "CK_CXC_FEL_TOTAL" CHECK (TOTAL > 0 AND SUBTOTAL_GRAVADO >= 0 AND IVA >= 0) ENABLE, 
	 CONSTRAINT "PK_CXC_FACTURA_FEL" PRIMARY KEY ("ID_FACTURA_FEL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_FEL_DOCUMENTO" UNIQUE ("ID_DOCUMENTO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_FEL_UUID" UNIQUE ("UUID_AUTORIZACION")
  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_FEL_SERIE_NUM" UNIQUE ("SERIE_FEL", "NUMERO_FEL")
  USING INDEX  ENABLE, 
	 CONSTRAINT "FK_CXC_FEL_DOCUMENTO" FOREIGN KEY ("ID_DOCUMENTO")
	  REFERENCES "CXC_DOCUMENTOS" ("ID_DOCUMENTO") ENABLE, 
	 CONSTRAINT "FK_CXC_FEL_EMPRESA" FOREIGN KEY ("ID_EMPRESA")
	  REFERENCES "CXC_EMPRESAS" ("ID_EMPRESA") ENABLE, 
	 CONSTRAINT "FK_CXC_FEL_EMP_EMISION" FOREIGN KEY ("ID_EMPLEADO_EMISION")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_FEL_EMP_ANULA" FOREIGN KEY ("ID_EMPLEADO_ANULACION")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE
   ) ;

