CREATE TABLE "CXC_NOTAS_CREDITO" 
   (	"ID_NOTA_CREDITO" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_CLIENTE" NUMBER NOT NULL ENABLE, 
	"ID_DOCUMENTO_REFERENCIA" NUMBER, 
	"DESCRIPCION" VARCHAR2(250), 
	"SERIE" VARCHAR2(30), 
	"NUMERO" VARCHAR2(30), 
	"FECHA" DATE NOT NULL ENABLE, 
	"MONTO" NUMBER(14,2) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'ACTIVA' NOT NULL ENABLE, 
	"ID_EMPLEADO_ANULACION" NUMBER, 
	"FECHA_ANULACION" DATE, 
	"MOTIVO_ANULACION" VARCHAR2(250), 
	"ID_EMPLEADO_REGISTRO" NUMBER, 
	"FECHA_REGISTRO" DATE, 
	"ID_EMPLEADO_APROBACION" NUMBER, 
	"FECHA_APROBACION" DATE, 
	 CONSTRAINT "PK_CXC_NOTAS_CREDITO" PRIMARY KEY ("ID_NOTA_CREDITO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_NC_ESTADO" CHECK (ESTADO IN ('PENDIENTE','APLICADA','ANULADA','ACTIVA')) ENABLE, 
	 CONSTRAINT "UQ_CXC_NC_SERIE_NUMERO" UNIQUE ("SERIE", "NUMERO")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_NC_APROBADOR_DISTINTO" CHECK (
    "ID_EMPLEADO_APROBACION" IS NULL
    OR "ID_EMPLEADO_REGISTRO" IS NULL
    OR "ID_EMPLEADO_APROBACION" <> "ID_EMPLEADO_REGISTRO"
  ) ENABLE, 
	 CONSTRAINT "FK_CXC_NC_CLIENTE" FOREIGN KEY ("ID_CLIENTE")
	  REFERENCES "CLIENTE" ("ID_CLIENTE") ENABLE, 
	 CONSTRAINT "FK_CXC_NC_DOC_REF" FOREIGN KEY ("ID_DOCUMENTO_REFERENCIA")
	  REFERENCES "CXC_DOCUMENTOS" ("ID_DOCUMENTO") ENABLE, 
	 CONSTRAINT "FK_CXC_NC_ANULACION" FOREIGN KEY ("ID_EMPLEADO_ANULACION")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_NC_REGISTRO" FOREIGN KEY ("ID_EMPLEADO_REGISTRO")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_NC_APROBACION" FOREIGN KEY ("ID_EMPLEADO_APROBACION")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE
   ) ;

