CREATE TABLE "CXC_RUTAS" 
   (	"ID_RUTA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"CODIGO_RUTA" VARCHAR2(30), 
	"NOMBRE" VARCHAR2(120) NOT NULL ENABLE, 
	"ID_EMPLEADO" NUMBER NOT NULL ENABLE, 
	"FECHA" DATE, 
	"ESTADO" VARCHAR2(20) DEFAULT 'PLANIFICADA' NOT NULL ENABLE, 
	"OBSERVACIONES" VARCHAR2(500), 
	"RADIO_KM" NUMBER(4,1) DEFAULT 5 NOT NULL ENABLE, 
	"ID_SUCURSAL" NUMBER, 
	 CONSTRAINT "PK_CXC_RUTAS" PRIMARY KEY ("ID_RUTA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_RUTAS_ESTADO" CHECK (ESTADO IN ('PLANIFICADA','EN_PROCESO','COMPLETADA','CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_CXC_RUTAS_RADIO" CHECK (RADIO_KM BETWEEN 1 AND 50) ENABLE, 
	 CONSTRAINT "FK_CXC_RUTAS_EMP" FOREIGN KEY ("ID_EMPLEADO")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_RUTAS_SUCURSAL" FOREIGN KEY ("ID_SUCURSAL")
	  REFERENCES "CXC_SUCURSALES" ("ID_SUCURSAL") ENABLE
   ) ;

-- CXC_RUTA_DETALLE
CREATE TABLE "CXC_RUTA_DETALLE" 
   (	"ID_RUTA_DETALLE" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"ID_RUTA" NUMBER NOT NULL ENABLE, 
	"ID_CLIENTE" NUMBER NOT NULL ENABLE, 
	"ORDEN_VISITA" NUMBER, 
	"DIRECCION" VARCHAR2(250), 
	"MONTO_PENDIENTE" NUMBER(14,2), 
	"ESTADO_VISITA" VARCHAR2(30) DEFAULT 'PENDIENTE', 
	"HORA_VISITA" VARCHAR2(10), 
	"OBSERVACIONES" VARCHAR2(500), 
	"ID_DOCUMENTO" NUMBER, 
	"ID_COBRADOR" NUMBER, 
	"MONTO_ASIGNADO" NUMBER(14,2), 
	"LATITUD" NUMBER(10,7), 
	"LONGITUD" NUMBER(11,7), 
	"HORA_PROGRAMADA" VARCHAR2(5), 
	 CONSTRAINT "PK_CXC_RUTA_DETALLE" PRIMARY KEY ("ID_RUTA_DETALLE")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_RD_ESTADO_VISITA" CHECK (ESTADO_VISITA IN ('PENDIENTE','VISITADO','NO_ENCONTRADO','REPROGRAMADO')) ENABLE, 
	 CONSTRAINT "CK_CXC_RD_ASIGNACION" CHECK (ID_DOCUMENTO IS NULL OR (ID_COBRADOR IS NOT NULL AND MONTO_ASIGNADO IS NOT NULL AND MONTO_ASIGNADO > 0 AND LATITUD IS NOT NULL AND LONGITUD IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_CXC_RD_LAT" CHECK (LATITUD BETWEEN -90 AND 90) ENABLE, 
	 CONSTRAINT "CK_CXC_RD_LON" CHECK (LONGITUD BETWEEN -180 AND 180) ENABLE, 
	 CONSTRAINT "CK_CXC_RD_HORA_PROG" CHECK (HORA_PROGRAMADA IS NULL OR REGEXP_LIKE(HORA_PROGRAMADA, '^([01][0-9]|2[0-3]):[0-5][0-9]$')) ENABLE, 
	 CONSTRAINT "FK_CXC_RUTA_DET_RUTA" FOREIGN KEY ("ID_RUTA")
	  REFERENCES "CXC_RUTAS" ("ID_RUTA") ENABLE, 
	 CONSTRAINT "FK_CXC_RUTA_DET_CLIENTE" FOREIGN KEY ("ID_CLIENTE")
	  REFERENCES "CLIENTE" ("ID_CLIENTE") ENABLE, 
	 CONSTRAINT "FK_CXC_RD_DOCUMENTO" FOREIGN KEY ("ID_DOCUMENTO")
	  REFERENCES "CXC_DOCUMENTOS" ("ID_DOCUMENTO") ENABLE, 
	 CONSTRAINT "FK_CXC_RD_COBRADOR" FOREIGN KEY ("ID_COBRADOR")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE
   ) ;

-- CXC_SOLICITUDES_REVERSA
CREATE TABLE "CXC_SOLICITUDES_REVERSA" 
   (	"ID_SOLICITUD" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE, 
	"TIPO" VARCHAR2(30) NOT NULL ENABLE, 
	"ID_REGISTRO" NUMBER NOT NULL ENABLE, 
	"REFERENCIA" VARCHAR2(200), 
	"MONTO" NUMBER(12,2), 
	"MOTIVO" VARCHAR2(250) NOT NULL ENABLE, 
	"ESTADO" VARCHAR2(10) DEFAULT 'PENDIENTE' NOT NULL ENABLE, 
	"ID_USUARIO_SOLICITA" NUMBER NOT NULL ENABLE, 
	"ID_EMPLEADO_SOLICITA" NUMBER NOT NULL ENABLE, 
	"FECHA_SOLICITUD" DATE DEFAULT SYSDATE NOT NULL ENABLE, 
	"ID_USUARIO_RESUELVE" NUMBER, 
	"FECHA_RESOLUCION" DATE, 
	"MOTIVO_RECHAZO" VARCHAR2(250), 
	 CONSTRAINT "CK_CXC_SR_TIPO" CHECK ("TIPO" IN (
    'REVERSA_APLICACION_PAGO', 'REVERSA_APLICACION_ANTICIPO', 'REVERSA_APLICACION_NC',
    'ANULACION_PAGO', 'ANULACION_ANTICIPO', 'ANULACION_NOTA_CREDITO',
    'ANULACION_DOCUMENTO', 'ANULACION_FACTURA_FEL')) ENABLE, 
	 CONSTRAINT "CK_CXC_SR_ESTADO" CHECK ("ESTADO" IN ('PENDIENTE', 'APROBADA', 'RECHAZADA', 'CANCELADA')) ENABLE, 
	 CONSTRAINT "CK_CXC_SR_RESUELVE_DISTINTO" CHECK (
    "ESTADO" IN ('PENDIENTE', 'CANCELADA')
    OR "ID_USUARIO_RESUELVE" <> "ID_USUARIO_SOLICITA") ENABLE, 
	 CONSTRAINT "CK_CXC_SR_RECHAZO_CON_MOTIVO" CHECK ("ESTADO" <> 'RECHAZADA' OR "MOTIVO_RECHAZO" IS NOT NULL) ENABLE, 
	 CONSTRAINT "PK_CXC_SOLICITUDES_REVERSA" PRIMARY KEY ("ID_SOLICITUD")
  USING INDEX  ENABLE, 
	 CONSTRAINT "FK_CXC_SR_USUARIO_SOLICITA" FOREIGN KEY ("ID_USUARIO_SOLICITA")
	  REFERENCES "SEG_USUARIOS" ("ID_USUARIO") ENABLE, 
	 CONSTRAINT "FK_CXC_SR_EMPLEADO_SOLICITA" FOREIGN KEY ("ID_EMPLEADO_SOLICITA")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_SR_USUARIO_RESUELVE" FOREIGN KEY ("ID_USUARIO_RESUELVE")
	  REFERENCES "SEG_USUARIOS" ("ID_USUARIO") ENABLE
   ) ;

