  USING INDEX  ENABLE, 
	 CONSTRAINT "UQ_CXC_AP_CLAVE_RUTA" UNIQUE ("CLAVE_RUTA")
  USING INDEX  ENABLE, 
	 CONSTRAINT "CK_CXC_AP_CLAVE_RUTA" CHECK ((ID_RUTA_DETALLE IS NULL AND CLAVE_RUTA IS NULL) OR (ID_RUTA_DETALLE IS NOT NULL AND CLAVE_RUTA IS NOT NULL)) ENABLE, 
	 CONSTRAINT "CK_CXC_AP_ESTADO" CHECK (ESTADO IN ('PENDIENTE', 'CONFIRMADA', 'REVERSADA', 'RECHAZADA')) ENABLE, 
	 CONSTRAINT "FK_CXC_APLIC_PAGO_PAGO" FOREIGN KEY ("ID_PAGO")
