	  REFERENCES "CXC_DOCUMENTOS" ("ID_DOCUMENTO") ENABLE, 
	 CONSTRAINT "FK_CXC_APLIC_PAGO_EMP" FOREIGN KEY ("ID_EMPLEADO")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_AP_REVERSA" FOREIGN KEY ("ID_EMPLEADO_REVERSA")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE, 
	 CONSTRAINT "FK_CXC_AP_RUTA_DET" FOREIGN KEY ("ID_RUTA_DETALLE")
	  REFERENCES "CXC_RUTA_DETALLE" ("ID_RUTA_DETALLE") ENABLE, 
	 CONSTRAINT "FK_CXC_AP_APROBADOR" FOREIGN KEY ("ID_EMPLEADO_APROBADOR")
	  REFERENCES "EMPLEADO" ("ID_EMPLEADO") ENABLE
   ) ;

