SET FEEDBACK ON

PROMPT Tablas creadas (debe ser 39):
SELECT COUNT(*) AS TABLAS_CREADAS FROM USER_TABLES WHERE TABLE_NAME IN ('CXC_CONDICIONES_CREDITO', 'CXC_EMPRESAS', 'CXC_FORMAS_PAGO', 'CXC_SEGMENTOS_CLIENTE', 'CXC_SUCURSALES', 'CXC_TIPOS_DOCUMENTO', 'CXC_TRAMOS_MORA', 'DEPARTAMENTO', 'EMPLEADO', 'MB_BANCO', 'MONEDA', 'SEG_BITACORA_ACCESO', 'SEG_USUARIOS', 'CLIENTE', 'CXC_CLIENTE_SEGMENTO', 'CXC_CONVENIOS_PAGO', 'CXC_CONVENIO_CUOTAS', 'CXC_DOCUMENTOS', 'CXC_DOCUMENTO_DETALLE', 'CXC_DOCUMENTO_HISTORIAL', 'CXC_FACTURA_FEL', 'CXC_MORA', 'CXC_NOTAS_CREDITO', 'CXC_PAGOS', 'CXC_RECIBOS', 'CXC_RUTAS', 'CXC_RUTA_DETALLE', 'CXC_SOLICITUDES_REVERSA', 'SEG_BITACORA_ACCION', 'SEG_RECUPERACION', 'SEG_SESIONES', 'CXC_AJUSTES', 'CXC_ANTICIPOS', 'CXC_APLICACION_ANTICIPO', 'CXC_APLICACION_NOTA_CREDITO', 'CXC_APLICACION_PAGOS', 'CXC_CONVENIO_DOCUMENTOS', 'CXC_GESTIONES_COBRO', 'CXC_PROMESAS_PAGO');

PROMPT Restricciones deshabilitadas (debe ser 0):
SELECT COUNT(*) AS RESTRICCIONES_DESHABILITADAS FROM USER_CONSTRAINTS WHERE STATUS <> 'ENABLED';

PROMPT Documentos cuyo saldo no cuadra con lo aplicado (debe ser 0):
SELECT COUNT(*) AS DOCUMENTOS_INCOHERENTES
  FROM CXC_DOCUMENTOS d
 WHERE d.ESTADO <> 'ANULADO'
   AND d.SALDO <> ROUND(d.TOTAL
         - NVL((SELECT SUM(a.MONTO_APLICADO) FROM CXC_APLICACION_PAGOS a WHERE a.ID_DOCUMENTO = d.ID_DOCUMENTO AND a.ESTADO = 'CONFIRMADA'), 0)
         - NVL((SELECT SUM(a.MONTO_APLICADO) FROM CXC_APLICACION_ANTICIPO a WHERE a.ID_DOCUMENTO = d.ID_DOCUMENTO AND a.ESTADO = 'CONFIRMADA'), 0)
         - NVL((SELECT SUM(a.MONTO_APLICADO) FROM CXC_APLICACION_NOTA_CREDITO a WHERE a.ID_DOCUMENTO = d.ID_DOCUMENTO AND a.ESTADO = 'CONFIRMADA'), 0)
         - NVL((SELECT SUM(CASE WHEN j.TIPO_AJUSTE = 'CREDITO' THEN j.MONTO ELSE -j.MONTO END) FROM CXC_AJUSTES j WHERE j.ID_DOCUMENTO = d.ID_DOCUMENTO AND j.ESTADO = 'APROBADO'), 0), 2);

